data.value:
.card { margin: 6px; padding: 14px; border: 1px solid @border; border-radius: 8px; background-color: @surface; color: @text; }
.card.active { border-left: 4px solid @success; }
.heading { display: flex; flex-direction: row; align-items: center; }
.icon { width: 36px; height: 36px; margin-right: 12px; }
.identity { flex-grow: 1; flex-shrink: 1; }
.name { font-size: 1.1em; font-weight: bold; }
.version { margin-top: 4px; color: @muted; }
.badge { margin-left: 8px; padding: 4px 8px; border-radius: 10px; background-color: @badge; color: @text; }
.active .badge { color: @success; }
.description { margin-top: 12px; margin-bottom: 12px; color: @muted; }
.commands { display: flex; flex-direction: row; justify-content: space-between; align-items: center; }
.details { color: @accent; padding: 6px 0; cursor: pointer; }
.button { padding: 7px 16px; border: 1px solid @accent; border-radius: 5px; color: @accent; cursor: pointer; }
.button:hover { background-color: @badge; }
.details:hover { text-decoration: underline; }
.empty { padding: 24px; color: @muted; }
